<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

class RecoveryCodesPanel
{
    /**
     * @param string[]|null $generatedCodes
     */
    public function render(
        int $unusedCount,
        string $regenerateUrl,
        string $cancelUrl,
        ?array $generatedCodes,
        array $t = [],
    ): string {
        $title = '<h1>' . ($t['title'] ?? 'Recovery codes') . '</h1>';

        $countLabel = $t['count'] ?? 'Unused recovery codes: %d';
        $countHtml = '<p>' . htmlspecialchars(sprintf($countLabel, $unusedCount)) . '</p>';

        $codesHtml = '';
        if ($generatedCodes !== null && $generatedCodes !== []) {
            $warning = htmlspecialchars($t['warning'] ?? 'Store these codes in a safe place. They will not be shown again.');
            $codesHtml = '<div class="recovery-codes-box">'
                . '<p class="recovery-codes-warning">' . $warning . '</p>'
                . '<ul class="recovery-codes-list">';
            foreach ($generatedCodes as $code) {
                $codesHtml .= '<li><code>' . htmlspecialchars($code) . '</code></li>';
            }
            $codesHtml .= '</ul></div>';
        }

        $regenerateLabel = htmlspecialchars($t['regenerate'] ?? 'Generate new codes');
        $backLabel = htmlspecialchars($t['back'] ?? 'Back to profile');
        $regenerateUrl = htmlspecialchars($regenerateUrl);
        $cancelUrl = htmlspecialchars($cancelUrl);

        $form = '<form method="POST" action="' . $regenerateUrl . '" class="profile-actions">'
            . '<input class="primary-button" type="submit" value="' . $regenerateLabel . '" />'
            . '<a class="secondary-button" href="' . $cancelUrl . '">' . $backLabel . '</a>'
            . '</form>';

        return $title . $countHtml . $codesHtml . $form;
    }
}
